/* GENERATED by scripts/build-atlas-data.cjs from atlas/graph/ — do not hand-edit. */
/* questions details for region "measurement", loaded on demand by atlas/app.js (ATLAS.loadDetails). */
window.ATLAS.addDetails("measurement.questions",{"questions":{
"q-averaging-leveling-0":{"target":{"node":"averaging-leveling","href":"../math/data/averaging-leveling/#step2"},"prompts":[{"node":"averaging-leveling","ask":{"zh":"把几杯不一样多的水倒匀，最后每杯水位一样高——倒匀前后，水的总量变了吗？","en":"If you pour several uneven cups until every cup is level, does the total amount of water change?"}},{"node":"bar-charts","ask":{"zh":"在条形图上画一条平均线，高出这条线的部分和低于这条线的部分有什么关系？","en":"On a bar chart, how does the part above the mean line relate to the part below it?"}}],"reveal":{"zh":"总量不变，倒匀后每杯都是总量÷杯数，所以平均数就是总数除以个数；图上的平均线正好让高出部分补上不足部分。","en":"The total never changes, and after levelling every cup holds total ÷ cups — that is why the mean is the total divided by the count, and the mean line on a chart is exactly where the excess fills the shortfall."},"source":"../math/data/averaging-leveling/#step2","lesson":"averaging-leveling"},
"q-bar-charts-0":{"target":{"node":"bar-charts","href":"../math/data/bar-charts/#step3"},"prompts":[{"node":"bar-charts","ask":{"zh":"柱子有高有低，平均线画在哪里，才会让高出部分刚好补平不足部分？","en":"With bars of different heights, where must the mean line sit so the excess exactly fills the shortfall?"}},{"node":"probability","ask":{"zh":"如果再来一个新数据，它落在平均线上面，会把平均数往上拉还是往下拉？","en":"If one new value lands above the mean line, does it pull the mean up or down?"}}],"reveal":{"zh":"平均线就是让高出与不足互相抵消的那条线；新数据高于平均线会把平均数往上拉，低于则往下拉。","en":"The mean line is the level where excess and shortfall cancel out; a new value above it pulls the mean up, below it pulls it down."},"source":"../math/data/bar-charts/#step3","lesson":"bar-charts"},
"q-clock-angles-0":{"target":{"node":"clock-angles","href":"../math/geometry/clock-angles/#step1"},"prompts":[{"node":"clock-angles","ask":{"zh":"分针每分钟走 6°，时针每分钟走 0.5°，分针每分钟追上时针多少度？","en":"The minute hand moves 6° per minute and the hour hand 0.5° — how many degrees does the minute hand gain each minute?"}},{"node":"unit-circle","ask":{"zh":"把一圈看成 360°，分针要追上多少度，才会再次和时针重合？","en":"Thinking of a full turn as 360°, how many degrees must the minute hand gain to catch the hour hand again?"}}],"reveal":{"zh":"每分钟追上 5.5°，追满一圈 360° 需要 360÷5.5 ≈ 65.5 分钟，所以大约每 1 小时 5 分半重合一次。","en":"It gains 5.5° per minute, so catching up a full 360° takes 360 ÷ 5.5 ≈ 65.5 minutes — the hands overlap about every 1 hour 5½ minutes."},"source":"../math/geometry/clock-angles/#step1","lesson":"clock-angles"},
"q-density-0":{"target":{"node":"density","href":"../physics/matter/density/#step2"},"prompts":[{"node":"density","ask":{"zh":"同种均匀材料，质量和体积成正比——画成质量-体积图，是一条直线吗？斜率是什么？","en":"For one uniform material, mass is proportional to volume — plotted as mass against volume, is it a straight line, and what is its slope?"}},{"node":"slope","ask":{"zh":"两块材料，图上斜率大的密度大还是小？密度大的放进水里会怎样？","en":"Of two materials, does the steeper line mean higher or lower density? What happens in water to the denser one?"}}],"reveal":{"zh":"质量÷体积 = 密度，图上斜率就是密度；密度比水大的下沉，比水小的上浮。","en":"Mass ÷ volume is density, which is exactly the slope of that line; denser than water sinks, less dense floats."},"source":"../physics/matter/density/#step2","lesson":"density"},
"q-mean-median-mode-0":{"target":{"node":"mean-median-mode","href":"../probability/statistics/mean-median-mode/#step1"},"prompts":[{"node":"mean-median-mode","ask":{"zh":"一个极端大的工资加入后，平均数、中位数、众数哪个动得最多？","en":"Add one extremely large salary — which moves most: the mean, the median, or the mode?"}},{"node":"variance","ask":{"zh":"中位数不怕极端值，但它丢失了什么信息？为什么工资报道常用中位数？","en":"The median resists extreme values, but what information does it throw away? Why do salary reports prefer it?"}}],"reveal":{"zh":"极端值会拉动平均数，却几乎不动中位数和众数；工资分布右偏严重时，中位数更能代表典型水平。","en":"An extreme value drags the mean but barely moves the median or mode; with salaries skewed high, the median better represents the typical level."},"source":"../probability/statistics/mean-median-mode/#step1","lesson":"mean-median-mode"},
"q-probability-frequency-0":{"target":{"node":"probability-vs-frequency","href":"../probability/basics/probability-frequency/#step4"},"prompts":[{"node":"probability-vs-frequency","ask":{"zh":"只挑出“前面连续五次正面”的那些情形，下一次正面的比例是多少？","en":"Among only the runs that began with five heads, what fraction showed heads next?"}},{"node":"probability","ask":{"zh":"硬币记得住之前的结果吗？独立是什么意思？","en":"Does a coin remember earlier results? What does independence mean?"}}],"reveal":{"zh":"每次转盘或抛币相互独立，过去的结果不会改变下一次的概率；“该轮到了”是赌徒谬误。大数定律说的是比例在很多次之后趋于稳定，靠的是新结果把早先的偏差稀释掉，而不是补偿回来。","en":"Each spin or toss is independent, so past results do not change the next probability; “it’s due” is the gambler’s fallacy. The law of large numbers says the proportion steadies over many trials because new results dilute an early imbalance, not because they compensate for it."},"source":"../probability/basics/probability-frequency/#step4","lesson":"probability-frequency"},
"q-bayes-diagnostics-0":{"target":{"node":"positive-predictive-value","href":"../probability/inference/bayes-diagnostics/#step-posterior"},"prompts":[{"node":"positive-predictive-value","ask":{"zh":"1000 个人里，真阳性和假阳性各有多少？阳性结果的分母是谁？","en":"Out of 1,000 people, how many true and false positives are there? What is the denominator of a positive result?"}},{"node":"bayes","ask":{"zh":"患病率（先验）变小时，同样准确的检测给出的后验会怎样变？","en":"If prevalence (the prior) is lower, what happens to the posterior from an equally accurate test?"}}],"reveal":{"zh":"阳性结果把你放进“所有阳性者”这一组，里面既有真病人也有假阳性的健康人。病越罕见，健康人越多，假阳性占比越大，所以即使检测很准，阳性预测值也可能远低于直觉。","en":"A positive result puts you in the group of everyone who tested positive, which holds both true patients and healthy false positives. The rarer the disease, the more healthy people there are and the larger the false-positive share, so even an accurate test can have a far lower positive predictive value than intuition suggests."},"source":"../probability/inference/bayes-diagnostics/#step-posterior","lesson":"bayes-diagnostics"},
"q-binomial-normal-0":{"target":{"node":"binomial-normal","href":"../probability/basics/binomial-normal/#step3"},"prompts":[{"node":"binomial-normal","ask":{"zh":"n 次独立试验恰好 k 次成功的概率怎么算？均值和方差是多少？","en":"How do you compute the chance of exactly k successes in n independent trials? What are its mean and variance?"}},{"node":"gaussian","ask":{"zh":"n 增大时，二项柱状图贴近什么样的曲线？“同均值同标准差”是什么意思？","en":"As n grows, what curve do the binomial bars hug? What does “same mean and same spread” mean?"}},{"node":"probability","ask":{"zh":"钟形曲线的高度代表什么？曲线下的面积为什么等于概率？","en":"What does the height of the bell curve stand for? Why does area under the curve equal probability?"}}],"reveal":{"zh":"由杨辉三角数路径得到二项分布，均值 np、方差 np(1−p)。n 增大时它贴近同均值同标准差的正态曲线，连续性修正补上离散与连续的缝隙。","en":"Counting paths in Pascal's triangle gives the binomial with mean np and variance np(1−p). As n grows it hugs the normal curve of the same mean and spread, with a continuity correction bridging the discrete-to-continuous gap."},"source":"../probability/basics/binomial-normal/#step3","lesson":"binomial-normal"},
"q-meiosis-0":{"target":{"node":"meiosis","href":"../biology/cells/meiosis/#step2"},"prompts":[{"node":"probability","ask":{"zh":"减数分裂两次分裂、染色体随机取向——n 对染色体能组合出几种配子？","en":"Meiosis divides twice with random chromosome alignment — how many gamete combinations do n pairs give?"}},{"node":"meiosis","ask":{"zh":"交换让同源染色体互换片段——交换后，配子的组合数是变多还是变少？","en":"Crossing over swaps segments between homologous chromosomes — does that raise or lower the number of gamete combinations?"}},{"node":"montecarlo","ask":{"zh":"如果随机模拟很多次受精，孩子完全相同的概率有多大？","en":"Simulating many random fertilisations, how likely are two children to come out identical?"}}],"reveal":{"zh":"随机取向给出 2ⁿ 种配子，交换又添新组合，两个配子随机结合，孩子几乎不可能完全相同。","en":"Random alignment gives 2ⁿ gametes, crossing over adds more combinations, and two random gametes combining make identical children vanishingly unlikely."},"source":"../biology/cells/meiosis/#step2","lesson":"meiosis"},
"q-natural-selection-0":{"target":{"node":"natural-selection","href":"../biology/ecology/natural-selection/#step2"},"prompts":[{"node":"probability","ask":{"zh":"胡椒蛾双色模型里，存活率差异怎样一代代改变颜色比例？","en":"In the two-colour peppered-moth model, how do survival differences shift the colour ratio generation by generation?"}},{"node":"natural-selection","ask":{"zh":"优势比越大，变化越快还是越慢？环境突然反向时，种群会立刻跟上吗？","en":"The bigger the advantage ratio, the faster or slower the change? If the environment flips suddenly, does the population follow at once?"}},{"node":"feedback","ask":{"zh":"小种群里随机漂变会怎样干扰选择？反馈和漂变哪个更能决定小种群的命运？","en":"In a small population, how does random drift interfere with selection? Which matters more for a small population's fate, feedback or drift?"}}],"reveal":{"zh":"存活率高的颜色留下更多后代，比例逐代递推上升；优势比决定速度，环境变化时种群会滞后跟上。","en":"The colour that survives better leaves more offspring, so its share climbs generation by generation; the advantage ratio sets the speed, and the population lags behind a changing environment."},"source":"../biology/ecology/natural-selection/#step2","lesson":"natural-selection"},
"q-probability-distribution-0":{"target":{"node":"probability-distribution","href":"../probability/basics/probability-distribution/#step0"},"prompts":[{"node":"probability","ask":{"zh":"每个结果的概率都已知时，把它们按结果排成一排，会看到什么？","en":"When every outcome's probability is known, what do you see if you line them up by outcome?"}},{"node":"probability-distribution","ask":{"zh":"条形的高度、重心、离散程度各由什么决定？右尾的面积回答什么问题？","en":"What decides the bars' heights, balance point, and spread? What question does the right tail's area answer?"}},{"node":"gaussian","ask":{"zh":"把条形变细变多，对称分布会趋向什么形状？为什么说那是同一现象的连续表示？","en":"As the bars get finer and more numerous, what shape does a symmetric distribution tend toward, and why is that the continuous representation of the same phenomenon?"}}],"reveal":{"zh":"每个结果的概率排成条形，就是分布。条形的重心是期望，条形离重心的加权平方距离是方差。","en":"Probabilities arranged by outcome form a distribution. The bars' balance point is the expectation, and their probability-weighted squared distance from it is the variance."},"source":"../probability/basics/probability-distribution/#step0","lesson":"probability-distribution"},
"q-regression-correlation-0":{"target":{"node":"regression-correlation","href":"../probability/statistics/regression-correlation/#step1"},"prompts":[{"node":"variance","ask":{"zh":"相关系数 r 说明点云多贴一条直线——r 接近 1、接近 0 各是什么意思？","en":"Correlation r says how tightly a cloud follows a line — what do r near 1 and r near 0 each mean?"}},{"node":"regression-correlation","ask":{"zh":"最小二乘线是让残差平方和最小的线——为什么用平方和，不用残差的和？","en":"The least-squares line minimises the sum of squared residuals — why squares, not just the sum of residuals?"}},{"node":"slope","ask":{"zh":"离群点和杠杆点会把直线拉偏吗？混杂因素和非线性关系会怎样误导解读？","en":"Can outliers and leverage points drag the line off? How do confounders and nonlinear relations mislead the reading?"}}],"reveal":{"zh":"r 度量贴合程度，最小二乘找残差平方和最小的线；但离群点、杠杆、混杂和非线性都会让直线误导，解读时要先看点云。","en":"r measures the fit, least squares finds the line minimising squared residuals — but outliers, leverage, confounders and nonlinearity can all mislead, so look at the cloud first."},"source":"../probability/statistics/regression-correlation/#step1","lesson":"regression-correlation"},
"q-statistical-inference-0":{"target":{"node":"confidence-interval","href":"../probability/inference/statistical-inference/#step1"},"prompts":[{"node":"confidence-interval","ask":{"zh":"真值是固定的还是随机的？每次重新抽样，变的是区间还是真值？","en":"Is the true value fixed or random? With each new sample, does the interval move or the true value?"}},{"node":"gaussian","ask":{"zh":"为什么样本均值的波动能用正态分布和 σ/√n 来描述？","en":"Why can the wobble of sample means be described by a normal curve with σ/√n?"}}],"reveal":{"zh":"真值是固定的，随机的是区间。95% 说的是这套“估计值 ± 1.96 个标准误”的做法：反复抽样时，长期约 95% 的区间会套住真值；对某一个已经算出的区间，它要么套住了、要么没有。","en":"The true value is fixed; the interval is what is random. The 95% describes the procedure “estimate ± 1.96 standard errors”: over repeated sampling about 95% of such intervals capture the true value. Any one interval already computed either contains it or does not."},"source":"../probability/inference/statistical-inference/#step1","lesson":"statistical-inference"},
"q-titration-curves-0":{"target":{"node":"titration-curves","href":"../chemistry/solutions/titration-curves/#step2"},"prompts":[{"node":"derivative","ask":{"zh":"突跃处斜率最大是什么意思？为什么斜率最大的点就是终点附近？","en":"What does it mean that the slope peaks at the leap? Why is the steepest point near the end point?"}},{"node":"titration-curves","ask":{"zh":"强酸和弱酸的曲线、突跃、半等当点有什么不同？指示剂按什么选？","en":"How do strong-acid and weak-acid curves, leaps and half-equivalence points differ? How is an indicator chosen?"}},{"node":"estimate","ask":{"zh":"终点读数怎样变成浓度估计？这个估计的不确定度来自哪里？","en":"How does an end-point reading become a concentration estimate? Where does that estimate's uncertainty come from?"}}],"reveal":{"zh":"强酸、弱酸被强碱滴定的 pH 曲线各有突跃与半等当点，突跃就是斜率最大处。用终点读数估算浓度，指示剂要选在突跃区间内变色。","en":"pH curves for strong and weak acids titrated by a strong base each have a leap and a half-equivalence point, and the leap is where the slope peaks. The end-point reading estimates the concentration, and the indicator must change colour inside the leap's interval."},"source":"../chemistry/solutions/titration-curves/#step2","lesson":"titration-curves"},
"q-bandit-arms-0":{"target":{"node":"bandit-arms","href":"../probability/stochastic/bandit-arms/#step2"},"prompts":[{"node":"montecarlo","ask":{"zh":"概率未知的几台机器——只拉目前最好的（贪心），会错过什么？","en":"With machines of unknown probability — pulling only the current best (greedy), what do you miss?"}},{"node":"bandit-arms","ask":{"zh":"ε-贪心、UCB、汤普森采样各怎样在尝试和利用之间分配拉动次数？","en":"How do ε-greedy, UCB and Thompson sampling each split pulls between trying and exploiting?"}},{"node":"bayes","ask":{"zh":"每拉一次都得到新信息——贝叶斯更新怎样改变你对每台机器的判断？","en":"Every pull brings new information — how does Bayesian updating change your judgement of each machine?"}}],"reveal":{"zh":"纯贪心会困在局部最优；UCB 给不确定性高的机器加分、汤普森采样按后验概率选，累计遗憾都比纯贪心低。","en":"Pure greed gets stuck at a local best; UCB bonuses uncertain machines and Thompson sampling draws by posterior probability, and both rack up less cumulative regret than pure greed."},"source":"../probability/stochastic/bandit-arms/#step2","lesson":"bandit-arms"},
"q-decision-trees-0":{"target":{"node":"decision-trees","href":"../computing/ml/decision-trees/#step1"},"prompts":[{"node":"probability","ask":{"zh":"熵衡量混乱——一刀切下去，怎样算这一刀好不好？","en":"Entropy measures disorder — after one cut, how do you judge whether it was a good cut?"}},{"node":"decision-trees","ask":{"zh":"按信息增益挑每一刀，贪心地长树——贪心保证全局最少问题吗？","en":"Picking each cut by information gain grows the tree greedily — does greed guarantee the fewest questions overall?"}}],"reveal":{"zh":"每刀选信息增益最大的切法，混乱下降最快；但贪心只看眼前一步，深度限制则是防止学到噪声。","en":"Each cut picks the largest information gain, dropping disorder fastest; but greed only looks one step ahead, and depth limits stop the tree from learning noise."},"source":"../computing/ml/decision-trees/#step1","lesson":"decision-trees"},
"q-entropy-0":{"target":{"node":"information-entropy","href":"../probability/stochastic/entropy/#step4"},"prompts":[{"node":"information-entropy","ask":{"zh":"为什么常见的符号该用短码、罕见的用长码？平均码长的下限是什么？","en":"Why should common symbols get short codes and rare ones long codes? What is the floor on the average length?"}},{"node":"probability","ask":{"zh":"符号出现的概率越不均匀，猜下一个符号是更容易还是更难？","en":"The more uneven the symbol probabilities, is the next symbol easier or harder to guess?"}}],"reveal":{"zh":"无损压缩平均每个符号至少要用 H = −Σ p log₂ p 个比特，哈夫曼编码能做到离这个下限不到 1 比特。符号越可预测，熵越低，能压得越小；完全随机的数据几乎压不动。","en":"Lossless compression needs on average at least H = −Σ p log₂ p bits per symbol, and Huffman coding gets within 1 bit of that floor. The more predictable the symbols, the lower the entropy and the smaller the file; truly random data barely compresses at all."},"source":"../probability/stochastic/entropy/#step4","lesson":"entropy"},
"q-hypothesis-testing-0":{"target":{"node":"hypothesis-testing","href":"../probability/inference/hypothesis-testing/#step0"},"prompts":[{"node":"hypothesis-testing","ask":{"zh":"p 值是零假设为真时出现至少同样极端结果的概率——p = 0.03 是说零假设为真的概率是 3% 吗？","en":"The p-value is the probability, if the null is true, of a result at least as extreme — does p = 0.03 mean the null has a 3% chance of being true?"}},{"node":"bayes","ask":{"zh":"α 是第一类错误的预算——同时做多次检验，总会碰到“显著”，为什么需要校正？","en":"α is the budget for type-I errors — running many tests at once will hit “significant” by chance, so why is correction needed?"}},{"node":"probability","ask":{"zh":"p 值和贝叶斯的后验概率有什么区别？哪个直接回答“假设为真吗”？","en":"How does a p-value differ from a Bayesian posterior? Which one directly answers “is the hypothesis true?”?"}}],"reveal":{"zh":"p 值不是假设为真的概率，只是零假设下极端结果的概率；α 是犯第一类错误的预算，多次检验不校正就会假阳性泛滥。","en":"A p-value is not the probability the hypothesis is true, only the probability of an extreme result under the null; α budgets type-I errors, and uncorrected multiple testing floods you with false positives."},"source":"../probability/inference/hypothesis-testing/#step0","lesson":"hypothesis-testing"},
"q-llm-sampling-0":{"target":{"node":"llm-sampling","href":"../computing/ml/llm-sampling/#step1"},"prompts":[{"node":"probability","ask":{"zh":"每一步把分数用 softmax 变成概率——温度整形是什么意思？温度高了，分布变平还是变尖？","en":"Each step turns scores into probabilities via softmax — what does temperature shaping do? Higher temperature: flatter or sharper distribution?"}},{"node":"llm-sampling","ask":{"zh":"top-k / top-p 截断尾巴——截断后，剩下的词是按概率随机抽，还是取概率最大的？","en":"Top-k / top-p trim the tail — after trimming, are the remaining words drawn randomly by probability, or is the most probable one taken?"}}],"reveal":{"zh":"每步先把分数变概率、温度整形、截断尾巴，再随机抽一个词；抽到的词接进上下文，下一轮重复——句子就是这样一个词一个词长出来的。","en":"Each step turns scores into probabilities, reshapes them with temperature, trims the tail, then draws one word at random; that word joins the context and the cycle repeats — sentences grow one word at a time."},"source":"../computing/ml/llm-sampling/#step1","lesson":"llm-sampling"},
"q-markov-chains-0":{"target":{"node":"markov-chains","href":"../probability/stochastic/markov-chains/#step3"},"prompts":[{"node":"markov-chains","ask":{"zh":"下一步只取决于当前状态时，n 步转移为什么是转移矩阵的 n 次幂？","en":"When the next step depends only on the current state, why is the n-step transition the n-th power of the transition matrix?"}},{"node":"eigen","ask":{"zh":"第二特征值 |λ₂| 怎样决定收敛速度？特征值 1 对应的方向有什么特殊含义？","en":"How does the second eigenvalue |λ₂| set the convergence speed? What is special about the direction belonging to eigenvalue 1?"}},{"node":"probability","ask":{"zh":"稳态 π（πP = π）是什么意思？长期比例和单步概率有什么不同？","en":"What does the steady state π (πP = π) mean? How does a long-run share differ from a single-step probability?"}}],"reveal":{"zh":"下一步只取决于当前状态，n 步转移是转移矩阵的 n 次幂。正常的链收敛到稳态 π（πP = π），速度由第二特征值 |λ₂| 决定，有吸收态的链没有中间稳态。","en":"The next step depends only on the current state, so n-step transitions are the n-th power of the transition matrix. An ordinary chain converges to a steady state π (πP = π) at a speed set by the second eigenvalue |λ₂|, while a chain with absorbing states has no in-between steady state."},"source":"../probability/stochastic/markov-chains/#step3","lesson":"markov-chains"},
"q-overfitting-0":{"target":{"node":"overfitting","href":"../computing/ml/overfitting/#step1"},"prompts":[{"node":"variance","ask":{"zh":"训练误差随灵活度单调下降——灵活度越高，训练误差越低，这能说明模型越好吗？","en":"Training error falls monotonically with flexibility — higher flexibility, lower training error: does that mean a better model?"}},{"node":"overfitting","ask":{"zh":"测试误差先降后升——转折点前后，模型分别在欠拟合还是过拟合？","en":"Test error falls then rises — before and after the turning point, is the model underfitting or overfitting?"}},{"node":"decision-trees","ask":{"zh":"决策树深度限制和岭回归各怎样压住过拟合？换批数据能看出什么？","en":"How do decision-tree depth limits and ridge regression each hold back overfitting? What does a fresh batch of data reveal?"}}],"reveal":{"zh":"灵活度太高，模型把噪声也学进去了，训练误差继续降、测试误差反而升；限制深度、加正则、换批验证都是在压住这一点。","en":"Too much flexibility lets the model learn the noise too: training error keeps falling while test error rises; depth limits, regularisation and fresh-batch validation all hold that in check."},"source":"../computing/ml/overfitting/#step1","lesson":"overfitting"},
"q-poisson-process-0":{"target":{"node":"poisson-process","href":"../probability/stochastic/poisson-process/#step2"},"prompts":[{"node":"probability","ask":{"zh":"恒定平均速率下随机到达——间隔服从什么分布？窗口内个数服从什么分布？","en":"Random arrivals at a constant average rate — what distribution do the gaps follow? The counts per window?"}},{"node":"poisson-process","ask":{"zh":"指数分布无记忆是什么意思？已经等了很久，下一个到达会更快来吗？","en":"What does the exponential distribution's memorylessness mean? After a long wait, does the next arrival come sooner?"}},{"node":"montecarlo","ask":{"zh":"独立泊松流合并与稀释后仍是泊松——模拟很多次，散度比能判断一组数据像不像泊松吗？","en":"Independent Poisson streams stay Poisson when merged or thinned — over many simulations, can the dispersion ratio judge whether data look Poisson?"}}],"reveal":{"zh":"间隔指数分布、个数泊松分布，指数分布无记忆——等多久都不影响下一次；合并与稀释后仍是泊松，散度比可以检验数据像不像泊松。","en":"Gaps are exponential, counts are Poisson, and exponential means memoryless — waiting longer changes nothing about the next arrival; merging and thinning stay Poisson, and the dispersion ratio tests whether data look Poisson."},"source":"../probability/stochastic/poisson-process/#step2","lesson":"poisson-process"},
"q-risk-pooling-0":{"target":{"node":"risk-pooling","href":"../probability/stochastic/risk-pooling/#step1"},"prompts":[{"node":"variance","ask":{"zh":"一个人 0 或 10000 元的赌局——人均损失的波动随人数怎样变？按 1/√N 缩小是什么意思？","en":"One person's $0-or-$10,000 gamble — how does the spread of average loss change with pool size? What does shrinking as 1/√N mean?"}},{"node":"risk-pooling","ask":{"zh":"人数多了，保费为什么能算准？破产概率怎样变？","en":"With more people, why can the premium be priced accurately? What happens to the ruin probability?"}},{"node":"gaussian","ask":{"zh":"共同灾难使波动停在下限——为什么人再多也没用？逆向选择又怎样让保费螺旋上升？","en":"A shared catastrophe floors the spread — why doesn't adding people help? And how does adverse selection spiral premiums upward?"}}],"reveal":{"zh":"人均损失波动按 1/√N 缩小，人越多保费越可算；但共同灾难让风险无法分散、逆向选择推高保费，保险的边界就在这里。","en":"Average-loss spread shrinks as 1/√N, so bigger pools price more accurately; but shared catastrophes cannot be diversified away and adverse selection pushes premiums up — those are insurance's boundaries."},"source":"../probability/stochastic/risk-pooling/#step1","lesson":"risk-pooling"},
"q-signal-detection-0":{"target":{"node":"signal-detection-theory","href":"../psychology/cognition/signal-detection/#step3"},"prompts":[{"node":"gaussian","ask":{"zh":"有信号和没信号时的证据强度各是一条钟形曲线，它们离得越远意味着什么？","en":"Evidence with and without a signal forms two bell curves; what does it mean when they are farther apart?"}},{"node":"signal-detection-theory","ask":{"zh":"把判据左右移，命中率和虚报率会怎样一起变？","en":"Moving the criterion left or right, how do the hit and false-alarm rates change together?"}}],"reveal":{"zh":"正确率混合了两件事：分得清（d′，两条分布离多远）和多愿意说“有”（判据 c）。一个人可以靠判据把正确率凑到 80%，另一个靠更大的 d′；用 d′ = z(H) − z(F) 拆开，或在 ROC 曲线上比谁更鼓向左上角，才看得出谁更会分辨。","en":"Accuracy mixes two things: telling apart (d′, how far apart the distributions are) and willingness to say yes (the criterion c). One observer can reach 80% through the criterion, another through a larger d′; separating them with d′ = z(H) − z(F), or seeing whose ROC curve bows further to the upper left, shows who discriminates better."},"source":"../psychology/cognition/signal-detection/#step3","lesson":"signal-detection"}
}});
